/**
 * Reference CV fixtures (generated by `node scripts/make-cv-fixtures.mjs`).
 * All people and companies are fictional.
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { extractedProfileSchema, type ExtractedProfile } from "@/lib/profile/schema";

export const CV_FIXTURE_DIR = path.dirname(fileURLToPath(import.meta.url));

export const CV_FIXTURES = ["cv-business-analyst", "cv-marketing", "cv-dev"] as const;
export type CvFixture = (typeof CV_FIXTURES)[number];

export function readCvPdf(name: CvFixture | "cv-scanned"): Uint8Array {
  return new Uint8Array(readFileSync(path.join(CV_FIXTURE_DIR, `${name}.pdf`)));
}

export function readExpected(name: CvFixture): ExtractedProfile {
  const raw = readFileSync(path.join(CV_FIXTURE_DIR, `${name}.expected.json`), "utf8");
  return extractedProfileSchema.parse(JSON.parse(raw));
}
